global_css:
/* UptimeFixer Safe Changes Manager - compact footer v1.2 */
.ufx-safe-footer,
.ufx-safe-footer * { box-sizing: border-box; }

.ufx-safe-footer {
  position: relative;
  width: 100%;
  overflow: hidden;
  background: #10202d;
  color: #f7fbff;
  font-family: inherit;
  border-top: 1px solid rgba(255,255,255,.07);
}

.ufx-safe-footer::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: #c8f15a;
}

.ufx-safe-footer__inner {
  width: min(1320px, calc(100% - 56px));
  margin: 0 auto;
  padding: 46px 0 18px;
}

.ufx-safe-footer__top {
  display: grid;
  grid-template-columns: minmax(250px,1.05fr) minmax(320px,1.25fr) minmax(170px,.75fr) minmax(170px,.75fr);
  gap: 52px;
  align-items: start;
}

.ufx-safe-footer__brand {
  max-width: 330px;
}

.ufx-safe-footer__logo {
  display: inline-flex;
  align-items: center;
  margin: 0 0 20px;
  text-decoration: none !important;
}

.ufx-safe-footer__logo img,
.ufx-safe-footer__logo .custom-logo {
  display: block;
  width: auto;
  max-width: 205px;
  max-height: 58px;
  height: auto;
  object-fit: contain;
  background: #fff;
  padding: 7px 11px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,.12);
  box-shadow: 0 8px 22px rgba(0,0,0,.12);
}

.ufx-safe-footer__logo .custom-logo-link {
  display: inline-flex;
}

.ufx-safe-footer__logo-text {
  color: #fff;
  font-size: 22px;
  font-weight: 700;
}

.ufx-safe-footer__eyebrow {
  margin: 0 0 8px;
  color: #c8f15a;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: .15em;
}

.ufx-safe-footer__brand h2 {
  margin: 0;
  color: #fff;
  font-size: 34px;
  line-height: 1.06;
  letter-spacing: -.035em;
  font-weight: 700;
}

.ufx-safe-footer__brand h2 span {
  color: #dafa86;
}

.ufx-safe-footer__intro {
  max-width: 320px;
  margin: 14px 0 0;
  color: rgba(239,245,250,.70);
  font-size: 14px;
  line-height: 1.65;
}

.ufx-safe-footer__cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 40px;
  margin-top: 18px;
  padding: 9px 15px;
  border: 1px solid #c8f15a;
  border-radius: 999px;
  background: #c8f15a;
  color: #10202d !important;
  text-decoration: none !important;
  font-size: 13px;
  line-height: 1;
  font-weight: 700;
  transition: transform .18s ease, background .18s ease;
}

.ufx-safe-footer__cta:hover {
  transform: translateY(-1px);
  background: #ddff86;
}

.ufx-safe-footer__cta-label {
  display: inline-flex;
  align-items: center;
}

.ufx-safe-footer__cta-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  color: #126bff;
  line-height: 1;
  transform: translateY(-1px);
  transition: transform .18s ease, color .18s ease;
}

.ufx-safe-footer__cta-icon svg {
  display: block;
  width: 18px;
  height: 18px;
  overflow: visible;
}

.ufx-safe-footer__cta-icon svg path {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ufx-safe-footer__cta:hover .ufx-safe-footer__cta-icon {
  transform: translate(2px,-3px);
  color: #0d5fe8;
}

.ufx-safe-footer__nav-section {
  min-width: 0;
}

.ufx-safe-footer__nav-section h3 {
  margin: 6px 0 18px;
  color: #fff;
  font-size: 12px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.ufx-safe-footer__nav-section ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.ufx-safe-footer__tools ul {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 30px;
}

.ufx-safe-footer__nav-section li {
  margin: 0 0 12px;
}

.ufx-safe-footer__nav-section a {
  display: inline-flex;
  color: rgba(235,242,248,.72);
  text-decoration: none !important;
  font-size: 14px;
  line-height: 1.4;
  transition: color .18s ease, transform .18s ease;
}

.ufx-safe-footer__nav-section a:hover {
  color: #c8f15a;
  transform: translateX(2px);
}

.ufx-safe-footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-top: 28px;
  padding-top: 16px;
  border-top: 1px solid rgba(255,255,255,.10);
}

.ufx-safe-footer__bottom p {
  margin: 0;
  color: rgba(231,239,246,.58);
  font-size: 12px;
  line-height: 1.45;
}

.ufx-safe-footer__bottom a {
  color: #79aaff;
  text-decoration: none !important;
  font-weight: 600;
}

.ufx-safe-footer__bottom a:hover {
  color: #c8f15a;
}

.ufx-safe-footer__heart {
  color: #ff6570;
}

@media (max-width: 1080px) {
  .ufx-safe-footer__inner {
    width: min(100% - 44px,1320px);
    padding-top: 42px;
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr 1.15fr 1fr;
    gap: 36px;
  }

  .ufx-safe-footer__brand {
    grid-column: 1 / -1;
    max-width: 600px;
  }

  .ufx-safe-footer__tools ul {
    column-gap: 24px;
  }
}

@media (max-width: 720px) {
  .ufx-safe-footer__inner {
    width: min(100% - 32px,1320px);
    padding: 38px 0 18px;
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr 1fr;
    gap: 32px 24px;
  }

  .ufx-safe-footer__brand {
    grid-column: 1 / -1;
  }

  .ufx-safe-footer__tools {
    grid-column: 1 / -1;
  }

  .ufx-safe-footer__brand h2 {
    font-size: 31px;
  }

  .ufx-safe-footer__logo img,
  .ufx-safe-footer__logo .custom-logo {
    max-width: 190px;
  }

  .ufx-safe-footer__bottom {
    flex-direction: column;
    align-items: flex-start;
    gap: 7px;
    margin-top: 28px;
  }
}

@media (max-width: 460px) {
  .ufx-safe-footer__inner {
    width: min(100% - 28px,1320px);
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr;
  }

  .ufx-safe-footer__brand,
  .ufx-safe-footer__tools {
    grid-column: auto;
  }

  .ufx-safe-footer__tools ul {
    grid-template-columns: 1fr 1fr;
    column-gap: 20px;
  }

  .ufx-safe-footer__brand h2 {
    font-size: 29px;
  }

  .ufx-safe-footer__cta {
    width: auto;
  }
}

/* UFX TARGETED HOME POLISH START */
/* Small, reversible homepage polish only. No layout/schema/URL changes. */
@media (min-width: 761px) {
  body.ufx-studio .studio-search {
    max-width: 560px;
    min-height: 58px;
    padding: 7px 8px 7px 18px;
    border: 1px solid #bcc7d1;
    border-radius: 14px;
    box-shadow: 0 8px 24px rgba(17,29,42,.07);
    transition: border-color .18s ease, box-shadow .18s ease, transform .18s ease;
  }

  body.ufx-studio .studio-search:focus-within {
    outline: 0;
    border-color: #2855ed;
    box-shadow: 0 0 0 4px rgba(40,85,237,.08), 0 10px 28px rgba(17,29,42,.08);
    transform: translateY(-1px);
  }

  body.ufx-studio .studio-search input[type=search] {
    padding: 11px 0;
    font-size: 15px;
  }

  body.ufx-studio .studio-search button {
    width: 42px;
    height: 42px;
    border-radius: 10px;
    background: #2855ed;
    color: #fff;
    transition: transform .18s ease, background .18s ease;
  }

  body.ufx-studio .studio-search button:hover {
    background: #1745d8;
    transform: translateY(-1px);
  }

  body.ufx-studio .studio-quick {
    margin-top: 4px;
    padding: 14px;
    gap: 10px;
    border: 1px solid #deded8;
    border-radius: 14px;
    background: rgba(255,255,255,.72);
    box-shadow: 0 8px 24px rgba(17,29,42,.035);
  }

  body.ufx-studio .studio-quick > div:first-child {
    padding: 8px 10px;
  }

  body.ufx-studio .studio-quick h2 {
    font-size: 17px;
    margin-bottom: 4px;
  }

  body.ufx-studio .studio-quick > a {
    min-height: 72px;
    padding: 12px;
    border: 1px solid rgba(16,25,35,.05);
    border-radius: 10px;
    box-shadow: none;
  }

  body.ufx-studio .studio-quick > a:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 20px rgba(17,29,42,.06);
  }

  body.ufx-studio .studio-collection {
    border-radius: 14px;
    border-color: rgba(16,25,35,.07);
    box-shadow: 0 4px 14px rgba(17,29,42,.025);
  }

  body.ufx-studio .studio-collection:hover {
    transform: translateY(-3px);
    box-shadow: 0 14px 28px rgba(17,29,42,.07);
  }

  body.ufx-studio .studio-card-bottom {
    border-top: 1px solid rgba(16,25,35,.055);
  }

  body.ufx-studio .studio-more a {
    background: rgba(255,255,255,.58);
    transition: transform .18s ease, border-color .18s ease, color .18s ease, background .18s ease;
  }

  body.ufx-studio .studio-more a:hover {
    transform: translateY(-1px);
    background: #fff;
  }
}
/* UFX TARGETED HOME POLISH END */

/* UFX FINAL HEADER POLISH START */
/* Final normalized header. Overrides accumulated legacy header rules without editing theme files. */
body .at-header {
  position: sticky !important;
  top: 0 !important;
  z-index: 10000 !important;
  background: rgba(255,255,255,.96) !important;
  border-bottom: 1px solid #e8edf2 !important;
  box-shadow: 0 6px 24px rgba(15,23,42,.045) !important;
  backdrop-filter: saturate(160%) blur(14px) !important;
  -webkit-backdrop-filter: saturate(160%) blur(14px) !important;
}

body .at-header-inner {
  min-height: 0 !important;
  height: 72px !important;
  display: grid !important;
  grid-template-columns: auto minmax(0,1fr) auto !important;
  align-items: center !important;
  gap: 28px !important;
}

body .at-header .at-logo {
  min-width: 0 !important;
  gap: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-self: start !important;
  text-decoration: none !important;
}

body .at-header .at-custom-logo.at-bundled-logo,
body .at-header .at-logo .custom-logo,
body .at-header .at-logo .at-custom-logo {
  display: block !important;
  width: auto !important;
  max-width: 196px !important;
  max-height: 46px !important;
  height: auto !important;
  object-fit: contain !important;
}

body .at-nav-clean {
  display: flex !important;
  justify-self: center !important;
  min-width: 0 !important;
}

body .at-nav-clean > ul {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 2px !important;
}

body .at-nav-clean > ul > li > a {
  position: relative !important;
  min-height: 40px !important;
  padding: 10px 12px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 5px !important;
  border-radius: 9px !important;
  background: transparent !important;
  color: #334155 !important;
  font-size: 13.5px !important;
  line-height: 1 !important;
  font-weight: 600 !important;
  letter-spacing: -.01em !important;
  white-space: nowrap !important;
  text-decoration: none !important;
  transition: color .18s ease, background .18s ease !important;
}

body .at-nav-clean > ul > li > a:hover,
body .at-nav-clean > ul > li.is-active > a,
body .at-nav-clean > ul > li.at-has-mega:hover > a {
  color: #1d4ed8 !important;
  background: #f1f5ff !important;
}

body .at-nav-clean > ul > li.is-active > a::after {
  display: none !important;
}

body .at-nav-clean .at-caret {
  margin-left: 1px !important;
  font-size: 9px !important;
  opacity: .62 !important;
}

body .at-header-right {
  justify-self: end !important;
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  flex-shrink: 0 !important;
}

/* Avoid two competing search actions in the desktop header. */
body .ufx-header-search {
  display: none !important;
}

body .at-header-cta {
  min-height: 42px !important;
  padding: 0 16px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 8px !important;
  border: 1px solid #2563eb !important;
  border-radius: 10px !important;
  background: #2563eb !important;
  color: #fff !important;
  box-shadow: 0 6px 16px rgba(37,99,235,.16) !important;
  font-size: 13px !important;
  line-height: 1 !important;
  font-weight: 700 !important;
  text-decoration: none !important;
  transition: transform .18s ease, background .18s ease, box-shadow .18s ease !important;
}

body .at-header-cta svg {
  width: 16px !important;
  height: 16px !important;
  flex: 0 0 auto !important;
}

body .at-header-cta:hover {
  transform: translateY(-1px) !important;
  background: #1d4ed8 !important;
  border-color: #1d4ed8 !important;
  color: #fff !important;
  box-shadow: 0 8px 20px rgba(37,99,235,.21) !important;
}

body .at-dark-toggle,
body .at-menu-toggle {
  width: 42px !important;
  height: 42px !important;
  padding: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  border: 1px solid #e2e8f0 !important;
  border-radius: 10px !important;
  background: #fff !important;
  color: #334155 !important;
  box-shadow: none !important;
  transition: color .18s ease, background .18s ease, border-color .18s ease !important;
}

body .at-dark-toggle:hover,
body .at-menu-toggle:hover {
  color: #2563eb !important;
  background: #f8faff !important;
  border-color: #cbd9ff !important;
}

/* Cleaner Collections dropdown. */
body .at-simple-tools-menu.at-mega-menu {
  width: 560px !important;
  max-width: calc(100vw - 32px) !important;
  top: calc(100% + 10px) !important;
  left: 50% !important;
  right: auto !important;
  transform: translate(-50%, 8px) !important;
  padding: 16px !important;
  border: 1px solid #e5eaf0 !important;
  border-radius: 18px !important;
  background: rgba(255,255,255,.99) !important;
  box-shadow: 0 22px 55px rgba(15,23,42,.13) !important;
}

body .at-has-mega:hover .at-simple-tools-menu.at-mega-menu,
body .at-has-mega:focus-within .at-simple-tools-menu.at-mega-menu {
  transform: translate(-50%,0) !important;
}

body .at-simple-tools-menu .at-mega-title {
  margin: 0 0 12px !important;
  padding: 2px 2px 12px !important;
}

body .at-simple-tools-menu .at-mega-grid {
  grid-template-columns: repeat(2,minmax(0,1fr)) !important;
  gap: 7px !important;
}

body .at-simple-tools-menu .at-mega-grid a {
  min-height: 52px !important;
  grid-template-columns: 34px 1fr 16px !important;
  gap: 9px !important;
  padding: 8px 9px !important;
  border-radius: 11px !important;
  border: 1px solid #eef2f6 !important;
}

body .at-simple-tools-menu .at-mega-icon {
  width: 34px !important;
  height: 34px !important;
  border-radius: 9px !important;
}

body .at-simple-tools-menu .at-mega-all {
  margin-top: 9px !important;
  min-height: 40px !important;
  padding: 9px 13px !important;
  border-radius: 10px !important;
}

/* Dark mode */
body.at-dark .at-header {
  background: rgba(15,23,42,.96) !important;
  border-bottom-color: #263449 !important;
}

body.at-dark .at-nav-clean > ul > li > a {
  color: #dbe4ef !important;
}

body.at-dark .at-nav-clean > ul > li > a:hover,
body.at-dark .at-nav-clean > ul > li.is-active > a,
body.at-dark .at-nav-clean > ul > li.at-has-mega:hover > a {
  color: #93b4ff !important;
  background: rgba(37,99,235,.14) !important;
}

body.at-dark .at-dark-toggle,
body.at-dark .at-menu-toggle {
  background: #182337 !important;
  color: #e5edf7 !important;
  border-color: #334155 !important;
}

/* Tablet / mobile */
@media (min-width: 1121px) {
  body .at-menu-toggle {
    display: none !important;
  }
}

@media (max-width: 1120px) {
  body .at-header-inner {
    height: 68px !important;
    grid-template-columns: auto 1fr auto !important;
    gap: 14px !important;
  }

  body .at-nav-clean {
    display: none !important;
  }

  body .at-menu-toggle {
    display: inline-flex !important;
  }

  body .at-header .at-custom-logo.at-bundled-logo,
  body .at-header .at-logo .custom-logo,
  body .at-header .at-logo .at-custom-logo {
    max-width: 178px !important;
    max-height: 42px !important;
  }
}

@media (max-width: 700px) {
  body .at-header-inner {
    height: 64px !important;
    gap: 8px !important;
  }

  body .at-header .at-custom-logo.at-bundled-logo,
  body .at-header .at-logo .custom-logo,
  body .at-header .at-logo .at-custom-logo {
    max-width: 158px !important;
    max-height: 38px !important;
  }

  body .at-header-cta {
    width: 40px !important;
    height: 40px !important;
    min-height: 40px !important;
    padding: 0 !important;
    border-radius: 10px !important;
  }

  body .at-header-cta span {
    display: none !important;
  }

  body .at-dark-toggle,
  body .at-menu-toggle {
    width: 40px !important;
    height: 40px !important;
  }
}

@media (max-width: 430px) {
  body .at-header .at-custom-logo.at-bundled-logo,
  body .at-header .at-logo .custom-logo,
  body .at-header .at-logo .at-custom-logo {
    max-width: 142px !important;
  }

  body .at-dark-toggle {
    display: none !important;
  }
}
/* UFX FINAL HEADER POLISH END */

/* UFX TRAFFIC ESTIMATOR SEO START */
.ufx-traffic-seo-guide{
  margin:0 0 34px;
  padding:30px;
  border:1px solid #e3e9ef;
  border-radius:18px;
  background:#fff;
  box-shadow:0 10px 30px rgba(15,23,42,.035);
}
.ufx-traffic-seo-guide h2{
  margin:0 0 14px;
  color:#10202d;
  font-size:30px;
  line-height:1.15;
  letter-spacing:-.03em;
}
.ufx-traffic-seo-guide h3{
  margin:26px 0 9px;
  color:#142433;
  font-size:19px;
  line-height:1.3;
}
.ufx-traffic-seo-guide p,
.ufx-traffic-seo-guide li{
  color:#5f6f7d;
  font-size:15px;
  line-height:1.72;
}
.ufx-traffic-seo-guide p{margin:0 0 14px}
.ufx-traffic-seo-guide ul{
  margin:10px 0 16px 20px;
  padding:0;
}
.ufx-traffic-seo-guide li{margin:0 0 7px}
.ufx-traffic-seo-guide__facts{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:12px;
  margin:20px 0 6px;
}
.ufx-traffic-seo-guide__fact{
  padding:16px;
  border:1px solid #e7edf2;
  border-radius:13px;
  background:#f8fafc;
}
.ufx-traffic-seo-guide__fact strong{
  display:block;
  margin-bottom:5px;
  color:#1d4ed8;
  font-size:14px;
}
.ufx-traffic-seo-guide__fact span{
  color:#64748b;
  font-size:12.5px;
  line-height:1.5;
}
.ufx-traffic-seo-guide__links{
  display:flex;
  flex-wrap:wrap;
  gap:9px;
  margin-top:18px;
}
.ufx-traffic-seo-guide__links a{
  display:inline-flex;
  align-items:center;
  min-height:38px;
  padding:8px 12px;
  border:1px solid #d9e3ff;
  border-radius:999px;
  background:#f7f9ff;
  color:#1d4ed8;
  font-size:13px;
  font-weight:700;
  text-decoration:none;
}
.ufx-traffic-seo-guide__links a:hover{
  border-color:#2563eb;
  background:#eef4ff;
}
@media(max-width:760px){
  .ufx-traffic-seo-guide{padding:22px 18px;border-radius:14px}
  .ufx-traffic-seo-guide h2{font-size:25px}
  .ufx-traffic-seo-guide__facts{grid-template-columns:1fr}
}
/* UFX TRAFFIC ESTIMATOR SEO END */
